const groupSelectorsJS = `(() => {
  const initialize = (form) => {
    const rows = form.querySelector("[data-selector-rows]");
    const updateRemoveButtons = () => {
      const buttons = rows.querySelectorAll("[data-remove-selector]");
      buttons.forEach((button) => { button.disabled = buttons.length === 1; });
    };
    form.addEventListener("click", (event) => {
      const add = event.target.closest("[data-add-selector]");
      if (add) {
        const row = document.createElement("div");
        row.className = "detailform selector-row";
        row.innerHTML = '<input class="input" name="selector_key" placeholder="key · team" aria-label="Selector key" required><input class="input" name="selector_value" placeholder="value · payments" aria-label="Selector value" required><button class="btn" type="button" data-remove-selector aria-label="Remove condition">−</button>';
        rows.appendChild(row);
        row.querySelector("input").focus();
        updateRemoveButtons();
        return;
      }
      const remove = event.target.closest("[data-remove-selector]");
      if (remove && rows.querySelectorAll(".selector-row").length > 1) {
        remove.closest(".selector-row").remove();
        updateRemoveButtons();
		return;
	  }
	  const previewButton = event.target.closest("[data-preview-selector]");
	  if (previewButton) {
		const output = form.querySelector("[data-selector-preview]");
		const keys = [...form.querySelectorAll('[name="selector_key"]')];
		const values = [...form.querySelectorAll('[name="selector_value"]')];
		const selector = {};
		keys.forEach((input, index) => {
		  if (input.value.trim()) selector[input.value.trim()] = (values[index]?.value || "").trim();
		});
		previewButton.disabled = true;
		if (output) output.textContent = "Validating selector…";
		fetch("/api/v1/groups/preview", {
		  method: "POST",
		  credentials: "same-origin",
		  headers: {"Content-Type":"application/json", "Accept":"application/json"},
		  body: JSON.stringify({selector, exclude_id: form.dataset.groupId || ""})
		})
		  .then(async (response) => {
			if (!response.ok) throw new Error((await response.text()).trim() || "Unable to preview selector");
			return response.json();
		  })
		  .then((result) => { if (output) output.textContent = "✓ Valid selector · " + result.matched + " Collector(s) currently match"; })
		  .catch((error) => { if (output) output.textContent = "⚠ " + error.message; })
		  .finally(() => { previewButton.disabled = false; });
      }
    });
    updateRemoveButtons();
  };
  document.querySelectorAll("[data-selector-form]").forEach(initialize);
})();`

type upcomingView struct{ Page, Title, Subtitle, Current, Upcoming string }

const configurationEditorJS = `(() => {
  const form = document.getElementById("configuration-editor-form");
  const content = document.getElementById("configuration-content");
  const baseline = document.getElementById("configuration-baseline");
  const preview = document.getElementById("configuration-preview");
  const previewButton = document.getElementById("configuration-preview-button");
  const versionInput = document.getElementById("configuration-new-version");
  const errorBox = document.getElementById("configuration-validation-error");
  if (!form || !content || !baseline || !errorBox) return;

  const submitButton = form.querySelector('button[type="submit"]');
  const editors = Array.from(form.querySelectorAll("[data-section-key]"));
  const tabs = Array.from(form.querySelectorAll("[data-section-tab]"));
  const panels = Array.from(form.querySelectorAll("[data-section-panel]"));
  const hasBaseline = form.dataset.hasBaseline === "true";
  const initialSections = editors.map((editor) => editor.value);
  let validated = false;

  const hasChanges = () => !hasBaseline || editors.some((editor, index) => editor.value !== initialSections[index]);
  const updateActionState = () => {
    const enabled = hasChanges();
    if (versionInput) versionInput.disabled = !enabled;
    if (previewButton) previewButton.disabled = !enabled;
    if (submitButton) submitButton.disabled = !enabled;
  };

  const selectTab = (key) => {
    tabs.forEach((tab) => tab.classList.toggle("active", tab.dataset.sectionTab === key));
    panels.forEach((panel) => panel.classList.toggle("active", panel.dataset.sectionPanel === key));
  };
  tabs.forEach((tab) => tab.addEventListener("click", () => selectTab(tab.dataset.sectionTab)));

  const clearValidation = () => {
    errorBox.hidden = true;
    errorBox.textContent = "";
    validated = false;
  };
  editors.forEach((editor) => editor.addEventListener("input", () => {
    clearValidation();
    updateActionState();
  }));
  updateActionState();

  const showError = (message) => {
    errorBox.textContent = message || "Configuration validation failed.";
    errorBox.hidden = false;
    errorBox.scrollIntoView({ behavior: "smooth", block: "nearest" });
  };
  const sections = () => Object.fromEntries(
    editors.map((editor) => [editor.dataset.sectionKey, editor.value])
  );
  const composeAndValidate = async () => {
    const response = await fetch("/api/v1/configurations/sections/compose", {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json", "Accept": "application/json" },
      body: JSON.stringify({ baseline: baseline.value, sections: sections() })
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok || !result.validation || !result.validation.valid) {
      throw new Error((result.validation && result.validation.error) || "Configuration validation failed.");
    }
    content.value = result.content;
    if (preview) preview.value = result.content;
    return result.content;
  };

  if (previewButton) previewButton.addEventListener("click", async () => {
    clearValidation();
    previewButton.disabled = true;
    try {
      await composeAndValidate();
      selectTab("complete_preview");
    } catch (error) {
      showError(error.message);
    } finally {
      updateActionState();
    }
  });

  form.addEventListener("submit", async (event) => {
    if (validated) return;
    event.preventDefault();
    clearValidation();
    if (submitButton) submitButton.disabled = true;
    try {
      await composeAndValidate();
      validated = true;
      form.requestSubmit(submitButton);
    } catch (error) {
      showError(error.message || "Unable to validate the configuration.");
    } finally {
      updateActionState();
    }
  });
})();`

const upcomingHTML = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FleetAMP</title><style>` + controlPlaneCSS + `</style></head><body><div class="shell">` + sideNav + `<main class="main"><header class="top"><div><div class="crumb">FleetAMP / {{.Title}}</div><div class="pagetitle">{{.Title}}</div><div class="subtitle">{{.Subtitle}}</div></div><div class="topactions"><div class="connection"><span class="dot"></span>OpAMP listening</div></div></header><div class="content"><section class="card"><div class="cardhead"><div><div class="cardtitle">Capability status</div><div class="cardsub">FleetAMP community preview</div></div><span class="badge warn">Upcoming</span></div><div class="cardbody"><h2 style="margin-top:0">Not production-ready yet</h2><p class="subtitle">{{.Upcoming}}</p>{{if .Current}}<div class="groupselector"><strong>Available today</strong><div class="tiny" style="margin-top:7px">{{.Current}}</div></div>{{end}}<p class="tiny">This page is intentionally visible so the product navigation reflects the planned control-plane experience without presenting unfinished functionality as available.</p></div></section></div></main></div></body></html>`

var upcomingPage = template.Must(template.New("upcoming").Parse(upcomingHTML))

// registerUIRoutes serves the dashboard and informational placeholder pages that are not backed by dedicated resource handlers.
func registerUIRoutes(mux *http.ServeMux) {
	mux.HandleFunc("GET /assets/fleetamp-logo-transparent.png", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "image/png")
		w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
		_, _ = w.Write(fleetAMPLogoPNG)
	})
	mux.HandleFunc("GET /assets/configuration-editor.js", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "text/javascript; charset=utf-8")
		w.Header().Set("Cache-Control", "no-store")
		_, _ = w.Write([]byte(configurationEditorJS))
	})
	mux.HandleFunc("GET /assets/group-selectors.js", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "text/javascript; charset=utf-8")
		w.Header().Set("Cache-Control", "no-store")
		_, _ = w.Write([]byte(groupSelectorsJS))
	})

	mux.HandleFunc("GET /assets/theme.js", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "text/javascript; charset=utf-8")
		w.Header().Set("Cache-Control", "no-store")
		_, _ = w.Write([]byte(themeJS))
	})

	pages := map[string]upcomingView{
		"/ai-insights":     {Page: "ai-insights", Title: "AI Insights", Subtitle: "Explore explainable fleet risks, anomalies and operational recommendations.", Current: "FleetAMP already records configuration state, validation results, drift, deployment outcomes and audit history—the evidence future analysis will use.", Upcoming: "Contributor opportunities include fleet anomaly detection, configuration risk scoring, capacity and cardinality recommendations, failure correlation and explainable remediation suggestions. AI output will remain advisory and subject to FleetAMP validation, RBAC and approval controls."},
		"/deployments":     {Page: "deployments", Title: "Deployments", Subtitle: "Track configuration rollouts, delivery results, failures and rollback.", Current: "Deployment history remains attached to each Collector when it changes ownership groups. Group moves are recorded in the audit trail as previous group → new group, and the new group's desired configuration is evaluated as the next managed state.", Upcoming: "A consolidated deployment timeline, fleet-wide canary stages and configurable health gates are Upcoming."},
		"/instrumentation": {Page: "instrumentation", Title: "Instrumentation Guides", Subtitle: "Follow technology-specific OpenTelemetry onboarding and validation guidance.", Upcoming: "Guided setup for languages, frameworks and platforms—including prerequisites, SDK or operator choices, required attributes, validation and troubleshooting—is Upcoming."},
		"/mcp":             {Page: "mcp", Title: "MCP Server", Subtitle: "Connect AI assistants to governed FleetAMP diagnostics and workflows.", Current: "FleetAMP's validation, scoped ownership, approvals, rollback and audit records provide the safety boundaries required for future tool access.", Upcoming: "A future Model Context Protocol server could expose read-only fleet discovery and diagnostics first, followed by tightly scoped change proposals. Mutating operations will respect RBAC, validate before submission, require approval where configured and remain fully audited."},
		"/pipelines":       {Page: "pipelines", Title: "Pipelines", Subtitle: "Visualize how telemetry is collected, processed and sent to destinations.", Upcoming: "Pipeline topology, receiver/processor/exporter visualization and policy management are Upcoming."},
		"/blueprints":      {Page: "blueprints", Title: "Telemetry Blueprints", Subtitle: "Build governed configurations from reusable telemetry patterns.", Current: "FleetAMP already provides explicit Collector configuration versions, section policies, validation, group approval and audited deployment.", Upcoming: "Blueprints will combine Instrumentation Guides, reusable Configuration Modules, Instrumentation Profiles and administrator-controlled Destination Profiles. Generated configuration will remain explicit, reviewable and subject to the existing validation and approval workflow."},
		"/settings":        {Page: "settings", Title: "Settings", Subtitle: "Manage FleetAMP identity, authorization, policies and integrations.", Upcoming: "UI-managed platform settings, identity, RBAC and integration configuration are Upcoming."},
	}
	for path, view := range pages {
		path, view := path, view
		mux.HandleFunc(path, func(w http.ResponseWriter, r *http.Request) {
			if r.URL.Path != path {
				http.NotFound(w, r)
				return
			}
			w.Header().Set("Content-Type", "text/html; charset=utf-8")
			_ = upcomingPage.Execute(w, view)
		})
	}
}

